// ---------------------------------------------------------------------------
// Placeholder geometry
// ---------------------------------------------------------------------------

const VIEW_BOX = "0 0 1000 620"

/** Sampled from the design tokens — CAD-derived fills belong in the data. */
const PLAN_COLORS = {
  wall: "#d6d2cd",
  walkway: "#f1efec",
  atrium: "#e4e0da",
} as const

const SHELL = { x: 40, y: 40, w: 920, h: 540 }
const ROW_TOP = { y: 62, h: 178 }
const ROW_BOTTOM = { y: 360, h: 178 }
const GUTTER = 10

interface Tenant {
  name: string
  category: MapUnitCategory
  description: string
}

/**
 * Lays a row of tenants across the shell as equal rectangles.
 *
 * Deliberately dumb — the real coordinates come out of the CAD file, and any
 * cleverness here would only have to be deleted then.
 */
function layoutRow(
  tenants: Tenant[],
  floorId: string,
  startIndex: number,
  row: { y: number; h: number }
): MapUnit[] {
  const total = SHELL.w - GUTTER * (tenants.length - 1)
  const width = total / tenants.length

  return tenants.map((tenant, index) => {
    const x = SHELL.x + index * (width + GUTTER)
    const right = x + width
    const bottom = row.y + row.h

    return {
      id: `${floorId}-${String(startIndex + index + 1).padStart(2, "0")}`,
      name: tenant.name,
      category: tenant.category,
      description: tenant.description,
      points: [
        [Math.round(x), row.y],
        [Math.round(right), row.y],
        [Math.round(right), bottom],
        [Math.round(x), bottom],
      ],
    }
  })
}

function buildFloor(
  id: string,
  label: string,
  summary: string,
  top: Tenant[],
  bottom: Tenant[]
): MapFloor {
  return {
    id,
    label,
    summary,
    viewBox: VIEW_BOX,
    decorations: [
      {
        id: "shell",
        path: `M${SHELL.x} ${SHELL.y} H${SHELL.x + SHELL.w} V${SHELL.y + SHELL.h} H${SHELL.x} Z`,
        fill: "none",
        stroke: PLAN_COLORS.wall,
        strokeWidth: 2,
      },
      {
        id: "walkway",
        path: `M${SHELL.x} 250 H${SHELL.x + SHELL.w} V350 H${SHELL.x} Z`,
        fill: PLAN_COLORS.walkway,
      },
      {
        id: "atrium",
        path: "M466 300 a34 34 0 1 0 68 0 a34 34 0 1 0 -68 0",
        fill: PLAN_COLORS.atrium,
        label: "Atrium",
        labelPoint: [500, 356],
      },
      {
        id: "escalator-west",
        path: "M170 268 H290 V332 H170 Z",
        fill: "none",
        stroke: PLAN_COLORS.wall,
        strokeWidth: 1.5,
        label: "Escalators",
        labelPoint: [230, 304],
      },
      {
        id: "escalator-east",
        path: "M710 268 H830 V332 H710 Z",
        fill: "none",
        stroke: PLAN_COLORS.wall,
        strokeWidth: 1.5,
        label: "Lifts",
        labelPoint: [770, 304],
      },
    ],
    units: [
      ...layoutRow(top, id, 0, ROW_TOP),
      ...layoutRow(bottom, id, top.length, ROW_BOTTOM),
    ],
  }
}

